#![cfg(sidereon_repo_tests)]
//! Oracle verification of the mean-of-date to GCRS rotation
//! (`mean_of_date_to_gcrs_matrix`, `gcrs_to_mean_of_date_matrix`) and the GCRS
//! analytic Sun and Moon (`sun_moon_gcrs`, `sun_moon_gcrs_at`,
//! `sun_moon_gcrs_at_tdb_seconds`) against Orekit 13.1.10 and the JPL DE440
//! ephemeris, at TT epochs from 1990 to 2050.
//!
//! Fixture: `tests/fixtures/bodies/sun_moon_gcrs_orekit.json`, generated by
//! `fixtures-generators/orekit_sun_moon_gcrs_oracle/generate.sh` (Orekit
//! 13.1.10, Hipparchus 4.0.3, orekit-data commit recorded in the fixture).
//!
//! The rotation. Orekit's `FramesFactory.getMOD(IERSConventions.IERS_2010)` is
//! the mean equator and equinox of date this crate's analytic series are
//! referred to: its parent is EME2000, the J2000 mean frame, reached from GCRF
//! through the IAU 2006 frame bias, and its transform from EME2000 is the IAU
//! 2006 precession `R3(chi_A) R1(-omega_A) R3(-psi_A) R1(eps_0)` (Capitaine,
//! Wallace & Chapront 2003; Wallace & Capitaine 2006; IERS Conventions 2010,
//! equations 5.39 and 5.40), the same factors as `gcrs_to_mean_of_date_matrix`.
//! Two conventions differ:
//!
//! 1. Frame bias. Orekit's EME2000 forms `xi_0 = d_psi_B sin(eps_0)` from
//!    `d_psi_B = -41.775 mas` and `eps_0 = 84381.448 arcsec`, which is
//!    `-16.61714 mas`; this crate's bias (as Skyfield's) uses the published
//!    rounded `xi_0 = -16.6170 mas`. The 0.14 microarcsecond difference is a
//!    constant rotation of 6.82e-13 rad about the GCRS y axis, which the tests
//!    compute from those constants, check on Orekit's bias alone, and remove
//!    before the tight comparisons.
//! 2. Time argument. Orekit evaluates the precession angles at TT
//!    (`IERSConventions.evaluateTC`); this crate takes TDB. TDB - TT stays under
//!    1.71 ms, over which the precession turns by at most 1.4e-14 rad. The tight
//!    comparisons evaluate the crate's matrix at Orekit's TT; the comparison at
//!    the crate's own TDB allows that 1.4e-14 rad.
//!
//! Largest disagreements over the 76 epochs (components of unit vectors): the
//! precession alone 1.3e-15; Orekit's frame bias, its `xi_0` convention
//! removed, 5.7e-15 (the second-order product `|xi_0 * da_0|` that this
//! crate's second-order bias matrix leaves out); mean of date to GCRS at
//! Orekit's TT 5.9e-15 with the convention removed and 6.84e-13 without; at the
//! crate's TDB 1.44e-14.
//!
//! The bodies. The analytic series are the low-precision formulae of the
//! Astronomical Almanac (sections C and D) in the form Montenbruck & Gill,
//! "Satellite Orbits" (2000), 3.3.2 and 3.3.3, present them. Their published
//! accuracy is the bound:
//!
//! - Sun: 0.01 deg from 1950 to 2050 for the apparent place the formula's mean
//!   longitude (corrected for aberration) describes. DE440 positions are
//!   geometric, so the bound adds the 20.5 arcsec annual aberration:
//!   `0.01 deg + 20.5 arcsec = 0.0157 deg`. The largest error here is 0.0102 deg
//!   (2041-10-02).
//! - Moon: errors "rarely exceed" 0.3 deg in ecliptic longitude and 0.2 deg in
//!   latitude, and 0.2 Earth radii in distance. The angle bound combines the
//!   two directions, `hypot(0.3, 0.2) = 0.3606 deg`; the distance bound is
//!   `0.2 * 6378.137 km`. The largest angle here is 0.346 deg (2026-11-27,
//!   where the longitude error alone is 0.335 deg), the largest distance error
//!   1087 km.
//!
//! The mean-of-date vectors read as GCRS (what the force models used before
//! they switched to the GCRS vectors) put the Sun 0.367 to 0.372 deg off
//! through November 2026, more than twenty times the Sun bound, and the Moon
//! outside its bound on six of the fifteen days sampled that month.

use serde::Deserialize;
use sidereon_core::astro::bodies::sun_moon::{
    sun_moon_eci, sun_moon_gcrs, sun_moon_gcrs_at, sun_moon_gcrs_at_tdb_seconds, SunMoon,
};
use sidereon_core::astro::constants::time::{DAYS_PER_JULIAN_CENTURY, J2000_JD, SECONDS_PER_DAY};
use sidereon_core::astro::frames::precession::{
    build_icrs_to_j2000, compute_skyfield_precession_matrix,
};
use sidereon_core::astro::frames::transforms::{
    gcrs_to_mean_of_date_matrix, mean_of_date_to_gcrs_matrix,
};
use sidereon_core::astro::time::{TimeScale, TimeScales};

const FIXTURE_JSON: &str = include_str!("fixtures/bodies/sun_moon_gcrs_orekit.json");

const ARCSEC_TO_RAD: f64 = std::f64::consts::PI / 648_000.0;

/// Orekit's EME2000 frame bias `xi_0 = d_psi_B sin(eps_0)` minus this crate's
/// `xi_0 = -16.6170 mas`: the constant rotation about the GCRS y axis between
/// the two frame biases (-6.82e-13 rad).
fn frame_bias_xi0_difference_rad() -> f64 {
    let orekit_xi0 = -0.041775 * libm::sin(84_381.448 * ARCSEC_TO_RAD);
    (orekit_xi0 - -0.0166170) * ARCSEC_TO_RAD
}

/// Largest change of the IAU 2006 precession over |TDB - TT| <= 1.71 ms: the
/// accumulated rotation runs at under 5040 arcsec per Julian century.
const TT_TDB_PRECESSION_RAD: f64 = 1.4e-14;

/// Sun: Astronomical Almanac low-precision accuracy plus the annual aberration
/// the geometric DE440 position does not contain (see the module docs).
const SUN_BOUND_DEG: f64 = 0.01 + 20.5 / 3600.0;
/// Moon: Astronomical Almanac 0.3 deg in longitude and 0.2 deg in latitude.
const MOON_BOUND_DEG: f64 = 0.360_555_127_546_398_9;
/// Moon: Astronomical Almanac 0.2 Earth radii in distance.
const MOON_DISTANCE_BOUND_M: f64 = 0.2 * 6_378_137.0;

#[derive(Debug, Deserialize)]
struct FixtureSource {
    orekit: String,
    hipparchus: String,
    orekit_data_commit: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    #[serde(rename = "_source")]
    source: FixtureSource,
    vectors: [[f64; 3]; 4],
    eme2000_to_gcrf: [[f64; 3]; 4],
    epochs: Vec<Epoch>,
}

#[derive(Debug, Deserialize)]
struct Epoch {
    set: String,
    tt: (i32, i32, i32, i32, i32, f64),
    tt_seconds: f64,
    tdb_seconds: f64,
    mod_to_gcrf: [[f64; 3]; 4],
    mod_to_eme2000: [[f64; 3]; 4],
    sun_gcrf_m: [f64; 3],
    moon_gcrf_m: [f64; 3],
    sun_mod_m: [f64; 3],
    moon_mod_m: [f64; 3],
}

impl Epoch {
    fn time_scales(&self) -> TimeScales {
        let (year, month, day, hour, minute, second) = self.tt;
        TimeScales::from_scale(TimeScale::Tt, year, month, day, hour, minute, second)
            .expect("TT calendar epoch")
    }

    /// The time scales with the precession argument at Orekit's TT.
    fn time_scales_at_tt(&self) -> TimeScales {
        let mut ts = self.time_scales();
        ts.jd_tdb = J2000_JD + self.tt_seconds / SECONDS_PER_DAY;
        ts
    }

    fn tt_centuries(&self) -> f64 {
        self.tt_seconds / (DAYS_PER_JULIAN_CENTURY * SECONDS_PER_DAY)
    }
}

fn fixture() -> Fixture {
    serde_json::from_str(FIXTURE_JSON).expect("Sun/Moon GCRS Orekit fixture")
}

fn dot(a: [f64; 3], b: [f64; 3]) -> f64 {
    a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
}

fn norm(a: [f64; 3]) -> f64 {
    dot(a, a).sqrt()
}

fn angle_deg(a: [f64; 3], b: [f64; 3]) -> f64 {
    let cross = [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    ];
    libm::atan2(norm(cross), dot(a, b)).to_degrees()
}

fn mul(m: &[[f64; 3]; 3], v: [f64; 3]) -> [f64; 3] {
    [dot(m[0], v), dot(m[1], v), dot(m[2], v)]
}

fn transpose(m: &[[f64; 3]; 3]) -> [[f64; 3]; 3] {
    [
        [m[0][0], m[1][0], m[2][0]],
        [m[0][1], m[1][1], m[2][1]],
        [m[0][2], m[1][2], m[2][2]],
    ]
}

fn max_abs_difference(a: [f64; 3], b: [f64; 3]) -> f64 {
    (0..3).map(|i| (a[i] - b[i]).abs()).fold(0.0, f64::max)
}

/// A GCRS vector of Orekit's (bias `xi_0` of Orekit) expressed with this
/// crate's bias: the rotation `R2(xi_0 Orekit - xi_0 crate)` (passive, as in
/// SOFA), to first order in the 6.82e-13 rad angle.
fn to_crate_frame_bias(v: [f64; 3]) -> [f64; 3] {
    let theta = frame_bias_xi0_difference_rad();
    [v[0] - theta * v[2], v[1], v[2] + theta * v[0]]
}

#[test]
fn fixture_records_the_pinned_oracle_and_spans_1990_to_2050() {
    let fixture = fixture();
    assert_eq!(fixture.source.orekit, "13.1.10");
    assert_eq!(fixture.source.hipparchus, "4.0.3");
    assert_eq!(
        fixture.source.orekit_data_commit,
        "2d6edc9118983d95c51303df05db16ada90b7ee2"
    );
    assert_eq!(fixture.epochs.len(), 76);
    let years: Vec<i32> = fixture.epochs.iter().map(|e| e.tt.0).collect();
    assert_eq!(years.iter().min(), Some(&1990));
    assert_eq!(years.iter().max(), Some(&2050));
    assert_eq!(
        fixture
            .epochs
            .iter()
            .filter(|e| e.set == "month_2026")
            .count(),
        15
    );
}

#[test]
fn frame_bias_differs_from_orekit_by_the_xi0_convention_only() {
    // Orekit EME2000 -> GCRF against B^T, B this crate's GCRS -> J2000 bias.
    let fixture = fixture();
    let theta = frame_bias_xi0_difference_rad();
    assert!((theta - -6.82e-13).abs() < 0.01e-13, "theta {theta:e}");
    let bias_t = transpose(&build_icrs_to_j2000());
    for (v, orekit) in fixture.vectors.iter().zip(fixture.eme2000_to_gcrf.iter()) {
        let ours = mul(&bias_t, *v);
        // Without the convention difference removed, the disagreement is the
        // 6.82e-13 rad rotation.
        let raw = max_abs_difference(ours, *orekit);
        assert!(raw <= theta.abs() * norm(*v) + 1.0e-14, "raw {raw:e}");
        // Removed, what remains is the second-order products of the bias
        // angles that the bias matrix's second-order form leaves out
        // (|xi_0 * da_0| = 5.7e-15) and rounding.
        let corrected = max_abs_difference(ours, to_crate_frame_bias(*orekit));
        assert!(corrected <= 1.0e-14, "corrected {corrected:e}");
    }
}

#[test]
fn precession_matches_orekit_mod_to_eme2000() {
    let fixture = fixture();
    for epoch in &fixture.epochs {
        let jd_tt = J2000_JD + epoch.tt_seconds / SECONDS_PER_DAY;
        let p_t = transpose(&compute_skyfield_precession_matrix(jd_tt).expect("precession"));
        for (v, orekit) in fixture.vectors.iter().zip(epoch.mod_to_eme2000.iter()) {
            let difference = max_abs_difference(mul(&p_t, *v), *orekit);
            // Same angles at the same TT: rounding of the two evaluations, and
            // of the Julian date (4.7e-10 day, 3e-16 rad of precession).
            assert!(
                difference <= 2.0e-15,
                "{:?}: precession differs from Orekit by {difference:e}",
                epoch.tt
            );
        }
    }
}

#[test]
fn mean_of_date_to_gcrs_matches_orekit_mod_to_gcrf() {
    let fixture = fixture();
    let theta = frame_bias_xi0_difference_rad();
    for epoch in &fixture.epochs {
        let at_tt = mean_of_date_to_gcrs_matrix(&epoch.time_scales_at_tt()).expect("at TT");
        let at_tdb = mean_of_date_to_gcrs_matrix(&epoch.time_scales()).expect("at TDB");
        let inverse_at_tt =
            gcrs_to_mean_of_date_matrix(&epoch.time_scales_at_tt()).expect("inverse at TT");
        for (v, orekit) in fixture.vectors.iter().zip(epoch.mod_to_gcrf.iter()) {
            let orekit_with_crate_bias = to_crate_frame_bias(*orekit);
            let ours = mul(&at_tt, *v);
            // As delivered: the xi_0 convention plus rounding.
            let raw = max_abs_difference(ours, *orekit);
            assert!(
                raw <= theta.abs() + 1.0e-14,
                "{:?}: MOD -> GCRF differs from Orekit by {raw:e}",
                epoch.tt
            );
            // The convention removed: the bias matrix's dropped second-order
            // products (under 6e-15) and rounding.
            let corrected = max_abs_difference(ours, orekit_with_crate_bias);
            assert!(
                corrected <= 1.0e-14,
                "{:?}: MOD -> GCRF at TT differs by {corrected:e} after the bias convention",
                epoch.tt
            );
            // At the crate's TDB the precession moves by up to 1.4e-14 rad.
            let at_crate_tdb = max_abs_difference(mul(&at_tdb, *v), orekit_with_crate_bias);
            assert!(
                at_crate_tdb <= 1.0e-14 + TT_TDB_PRECESSION_RAD,
                "{:?}: MOD -> GCRF at TDB differs by {at_crate_tdb:e}",
                epoch.tt
            );
            // The inverse takes Orekit's GCRF vector back to the MOD vector.
            let back = max_abs_difference(mul(&inverse_at_tt, orekit_with_crate_bias), *v);
            assert!(
                back <= 1.0e-14,
                "{:?}: GCRS -> MOD differs by {back:e}",
                epoch.tt
            );
        }
    }
}

fn assert_within_series_accuracy(epoch: &Epoch, label: &str, bodies: SunMoon) {
    let sun_deg = angle_deg(bodies.sun, epoch.sun_gcrf_m);
    assert!(
        sun_deg <= SUN_BOUND_DEG,
        "{:?} {label}: Sun {sun_deg} deg from DE440 (bound {SUN_BOUND_DEG})",
        epoch.tt
    );
    let moon_deg = angle_deg(bodies.moon, epoch.moon_gcrf_m);
    assert!(
        moon_deg <= MOON_BOUND_DEG,
        "{:?} {label}: Moon {moon_deg} deg from DE440 (bound {MOON_BOUND_DEG})",
        epoch.tt
    );
    let moon_distance_m = (norm(bodies.moon) - norm(epoch.moon_gcrf_m)).abs();
    assert!(
        moon_distance_m <= MOON_DISTANCE_BOUND_M,
        "{:?} {label}: Moon distance off by {moon_distance_m} m",
        epoch.tt
    );
}

#[test]
fn gcrs_sun_and_moon_stay_within_the_series_accuracy_against_de440() {
    let fixture = fixture();
    let (mut sun_max, mut moon_max) = (0.0_f64, 0.0_f64);
    for epoch in &fixture.epochs {
        let gcrs = sun_moon_gcrs(epoch.tt_centuries()).expect("sun_moon_gcrs");
        assert_within_series_accuracy(epoch, "sun_moon_gcrs", gcrs);
        assert_within_series_accuracy(
            epoch,
            "sun_moon_gcrs_at",
            sun_moon_gcrs_at(&epoch.time_scales()).expect("sun_moon_gcrs_at"),
        );
        assert_within_series_accuracy(
            epoch,
            "sun_moon_gcrs_at_tdb_seconds",
            sun_moon_gcrs_at_tdb_seconds(epoch.tdb_seconds).expect("sun_moon_gcrs_at_tdb_seconds"),
        );
        sun_max = sun_max.max(angle_deg(gcrs.sun, epoch.sun_gcrf_m));
        moon_max = moon_max.max(angle_deg(gcrs.moon, epoch.moon_gcrf_m));

        // The series is a mean-of-date series: against DE440 in Orekit's MOD
        // frame it errs by the same angles as the GCRS vectors in GCRF, to the
        // rotation's 7e-13 rad (4e-11 deg) disagreement with Orekit.
        let mean = sun_moon_eci(epoch.tt_centuries()).expect("sun_moon_eci");
        let sun_in_mod = angle_deg(mean.sun, epoch.sun_mod_m);
        let moon_in_mod = angle_deg(mean.moon, epoch.moon_mod_m);
        assert!((sun_in_mod - angle_deg(gcrs.sun, epoch.sun_gcrf_m)).abs() <= 1.0e-10);
        assert!((moon_in_mod - angle_deg(gcrs.moon, epoch.moon_gcrf_m)).abs() <= 1.0e-10);
    }
    // The largest errors, as the module docs state them.
    assert!((sun_max - 0.0102).abs() < 0.0001, "Sun {sun_max} deg");
    assert!((moon_max - 0.346).abs() < 0.001, "Moon {moon_max} deg");
}

#[test]
fn mean_of_date_vectors_read_as_gcrs_break_the_bound_at_2026() {
    let fixture = fixture();
    let mut moon_outside = 0;
    for epoch in fixture.epochs.iter().filter(|e| e.set == "month_2026") {
        let mean = sun_moon_eci(epoch.tt_centuries()).expect("sun_moon_eci");
        let sun_deg = angle_deg(mean.sun, epoch.sun_gcrf_m);
        assert!(
            sun_deg > SUN_BOUND_DEG && (0.36..0.38).contains(&sun_deg),
            "{:?}: mean-of-date Sun read as GCRS is {sun_deg} deg from DE440",
            epoch.tt
        );
        if angle_deg(mean.moon, epoch.moon_gcrf_m) > MOON_BOUND_DEG {
            moon_outside += 1;
        }
        // The GCRS vectors at the same epoch are inside both bounds.
        let gcrs = sun_moon_gcrs(epoch.tt_centuries()).expect("sun_moon_gcrs");
        assert!(angle_deg(gcrs.sun, epoch.sun_gcrf_m) <= SUN_BOUND_DEG);
        assert!(angle_deg(gcrs.moon, epoch.moon_gcrf_m) <= MOON_BOUND_DEG);
    }
    assert_eq!(moon_outside, 6, "2026 days with the Moon outside its bound");
}
